defineRecipe.example:
const sage = 'b9de1d84-a0c1-4b81-9f60-8d7fbb3cb9d4';

kcds.world.Crafting.defineRecipe({
  kind: 'alchemy',
  id: 910001,
  name: 'Sage tonic',
  icon: 'potion_hair_o_dog',
  base: 'Water',
  usage: 'Drink it before a long ride.',
  baseXP: 10,
  ingredients: [{ item: sage, amount: 2 }],
  products: [{ item: '7a1e8447-4449-473b-aac9-63f7a324fa0b', threshold: 1, maxYield: 2 }],
  steps: [
    { id: 1, type: 'Trivial', condition: `PotionBase() AND IngredientCount('${sage}') >= 1` },
    { id: 2, type: 'Easy', condition: `IsMilled('${sage}', 1)`, text: 'Mill the sage.' },
  ],
});

