addRecipe.example:
const { Crafting } = kcds.world;

Crafting.addRecipe({
  id: 'smoked_boar',
  name: 'Smoked boar',
  ingredients: [{ item: 'boarMeat', amount: 2 }],
  products: [{ item: 'boarMeatSmoked', amount: 2 }],
  duration: 8,
});

const smokehouse = Crafting.addStation({
  position: new kcds.math.Vector3(100, 200, 10),
  recipes: ['smoked_boar'],
  text: 'Smoke meat',
});

kcds.core.Events.on('craftingStationUsed', (player, { station }) => {
  if (station === smokehouse) {
    Crafting.craft(player, station, 'smoked_boar');
  }
});

addRecipe.exampleCs:
Crafting.AddRecipe(new { id = "smoked_boar", name = "Smoked boar", ingredients = new object[] { new { item = "boarMeat", amount = 2 } }, products = new object[] { new { item = "boarMeatSmoked", amount = 2 } }, duration = 8 });

var smokehouse = Crafting.AddStation(new { position = new Vector3(100, 200, 10), recipes = new[] { "smoked_boar" }, text = "Smoke meat" });

Events.On("craftingStationUsed", (Player player, JsValue data) =>
{
    var station = data["station"];
    if (station.AsString() == smokehouse)
    {
        Crafting.Craft(player, station, "smoked_boar");
    }
});

